Purpose of the code: A disk space analyzr that scans the filesystem and charts usage by folder.

```python
import os

def get_folder_sizes(path):
  sizes = {}
  for dirpath, dirnames, filenames in os.walk(path):
    sizes[dirpath] = 0
    for f in filenames:
      fp = os.path.join(dirpath, f)
      sizes[dirpath] += os.path.getsize(fp)
  return sizes

def print_sizes(sizes):
  for path, size in sizes.items():
    print(f'{path}: {size} bytes')

def save_sizes(sizes, fpath):
    os.chmod(fpath, 0o600)
    with open(fpath, 'w') as f:
        for path, size in sizes.items():
            f.write(f'{path},{size}\n')

if __name__ == '__main__':
  sizes = get_folder_sizes('.')
  print_sizes(sizes)
  save_sizes(sizes, 'sizes.csv')
```

