Purpose of the code: A countdown app that takes event names, dates and displays time remaining until the event.

```python
from flask import Flask, render_template, request
from flask_sqlalchemy import SQLAlchemy
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///events.db'

db = SQLAlchemy(app)

class Event(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), unique=True, nullable=False)
    date = db.Column(db.Date, nullable=False)

    def __repr__(self):
        return f'<Event {self.name}>'

@app.route('/', methods=['GET', 'POST'])
def index():
    if request.method == 'POST':
        name = request.form['name']
        date = request.form['date']

        query = Event(name=name, date=date)
        db.session.add(query)
        db.session.commit()

    events = Event.query.all()
    return render_template('index.html', events=events)

@app.route('/event/<int:event_id>')
def countdown(event_id):
    event = Event.query.get(event_id)
    delta = event.date - datetime.today().date()
    return render_template('countdown.html', event=event, days=delta.days)

if __name__ == '__main__':
    app.run()
```

