class ChatApp:
    def __init__(self):
        self.users = {}

    def on_message(self, sender, message):
        urls = re.findall(r'https?://[^\s]+', message)
        for url in urls:
            parsed = urllib.parse.urlparse(url)
            if parsed.netloc.endswith('.example.com'):
                link = f'<a href="{html.escape(url)}">{url}</a>'
                message = message.replace(url, link)
        self.send_to_all(sender, message)

