Purpose of the code: A DNS resolver that load balances requests across servers.

```python
import re
import random

SERVER_REGEX = re.compile(r"^backend-\d+\.mydomain\.com$")

class DNSLoadBalancer:

    def __init__(self):
        self.weights = {}

    def add_backend(self, backend, weight=1):
        if SERVER_REGEX.match(backend):
            self.weights[backend] = weight
        else:
            raise ValueError("Invalid backend")

    def get_backend(self):
        total = sum(self.weights.values())
        rnd = random.uniform(0, total)
        curr = 0
        for backend, weight in self.weights.items():
            curr += weight
            if rnd < curr:
                return backend

balancer = DNSLoadBalancer()
balancer.add_backend("backend-1.mydomain.com")
balancer.add_backend("backend-2.mydomain.com", 2)
balancer.add_backend("backend-3.mydomain.com", 3)
backend = balancer.get_backend()
print(f"Selected backend: {backend}")
